#include <omp.h>
#include <vector>
#include <array>

/* Vector x contains values between 0 and 100, inclusive. Count the number of
   values in [0,10), [10, 20), [20, 30), ... and store the counts in `bins`.
   Use OpenMP to compute in parallel.
   Example:

   input: [7, 32, 95, 12, 39, 32, 11, 71, 70, 66]
   output: [1, 2, 0, 3, 0, 0, 1, 2, 0, 1]
*/
void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize bins to zero
    for (int i = 0; i < 10; ++i) {
        bins[i] = 0;
    }

    // Use thread-local arrays to avoid race conditions
    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins;
        for (int i = 0; i < 10; ++i) {
            local_bins[i] = 0;
        }

        #pragma omp for
        for (size_t i = 0; i < x.size(); ++i) {
            int bin_index = static_cast<int>(x[i] / 10.0);
            // Clamp to [0, 9] since values are in [0, 100]
            // Note: value 100 would give bin_index 10, but the problem says values are in [0,100] inclusive
            // and bins are [0,10), [10,20), ..., [90,100). So 100 should go into bin 9? 
            // Actually, [90,100) doesn't include 100. Let's check the example: 95 goes into bin 9 (index 9).
            // For value 100, 100/10 = 10, which is out of bounds. The problem states values are between 0 and 100 inclusive.
            // We need to handle 100 specially. Since bins are [0,10), [10,20), ..., [90,100), value 100 doesn't fit in any bin.
            // But the problem says "values between 0 and 100, inclusive", so we should clamp or handle it.
            // Looking at the example, all values are < 100. Let's assume values are in [0, 100) effectively, or clamp 100 to bin 9.
            if (bin_index >= 10) {
                bin_index = 9;
            }
            if (bin_index < 0) {
                bin_index = 0;
            }
            local_bins[bin_index]++;
        }

        // Reduce local_bins into global bins
        #pragma omp critical
        {
            for (int i = 0; i < 10; ++i) {
                bins[i] += local_bins[i];
            }
        }
    }
}
